toolArgs.file_text:
.catalog-layout {
    display: flex;
    gap: 1.5rem;
    padding: 1rem;
}

.catalog-main {
    flex: 1;
    min-width: 0;
}

.catalog-loading,
.catalog-error,
.catalog-empty {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 3rem;
    text-align: center;
}

.catalog-error {
    color: #dc3545;
}

::deep .catalog-filters {
    width: 25%;
    min-width: 220px;
    padding: 1rem;
    border-right: 1px solid #e0e0e0;
}

::deep .filter-section {
    margin-bottom: 1.5rem;
}

::deep .filter-section h3 {
    margin-bottom: 0.5rem;
    font-size: 0.9rem;
    font-weight: 600;
}

::deep .filter-checkbox {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-bottom: 0.25rem;
    cursor: pointer;
}

::deep .filter-section label {
    display: block;
    margin-bottom: 0.5rem;
}

::deep .filter-section input[type="number"] {
    width: 100%;
    padding: 0.25rem 0.5rem;
    border: 1px solid #ccc;
    border-radius: 4px;
}

::deep .filter-actions {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

::deep .btn-apply,
::deep .btn-clear {
    padding: 0.5rem 1rem;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

::deep .btn-apply {
    background-color: #0d6efd;
    color: white;
}

::deep .btn-clear {
    background-color: #6c757d;
    color: white;
}

::deep .catalog-toolbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
    padding: 0.75rem;
    background: #f8f9fa;
    border-radius: 4px;
}

::deep .toolbar-sort {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

::deep .toolbar-sort select {
    padding: 0.25rem 0.5rem;
    border: 1px solid #ccc;
    border-radius: 4px;
}

::deep .product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 1rem;
}

::deep .product-card {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    overflow: hidden;
    cursor: pointer;
    transition: box-shadow 0.2s;
}

::deep .product-card:hover {
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15);
}

::deep .product-image {
    background: #e9ecef;
    height: 160px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #6c757d;
